/* DEMO 10.108.18 — quiz result flow + stable two-line descriptions + linked mouth/airflow visual.
   Builds on 10.108.17 visual/mouth polish + readable initial models + explicit tone-placement rule.
   Primary listening uses a native-style helper syllable (呼読音); pure consonant/airflow remains a secondary contrast.
   b/p/m/f cards now share one deliberate hierarchy instead of relying on text wrapping.
   
   Local WAV is the primary path so iPhone Safari/Private mode can play on the first tap.
   Web Audio remains only as a fallback. These are vowel-free prototype sounds;
   the final course should still replace them with one native Mandarin speaker. */
(function(){
  var letters=['b','p','m','f'];
  var sounds={
    b:{mark:'[p]',label:'無気音',desc:'母音を足さず、くちびるを閉じて一瞬だけ開く'},
    p:{mark:'[pʰ]',label:'有気音',desc:'母音を足さず、同じ口の形で開く瞬間に強く息を出す'},
    m:{mark:'[m]',label:'鼻音',desc:'母音を足さず、くちびるを閉じたまま鼻に短く響かせる'},
    f:{mark:'[f]',label:'摩擦音',desc:'母音を足さず、上の歯を下くちびるに軽く当てて細く息を流す'}
  };
  var guide={
    b:{hanzi:'波',pinyin:'bō'},
    p:{hanzi:'泼',pinyin:'pō'},
    m:{hanzi:'摸',pinyin:'mō'},
    f:{hanzi:'佛',pinyin:'fó'}
  };
  var tips={
    b:'くちびるを閉じる → 一瞬だけ開く。母音を足さない（無気音）',
    p:'b と同じ口 → 開く瞬間に強く息を出す（有気音）',
    m:'くちびるを閉じたまま、鼻から「んー」と響かせる',
    f:'上の歯を下くちびるに軽く当て、口角は大きく横に引かず、細い息を流す'
  };
  var focusVisuals={
    b:{title:'両くちびるを閉じる',sub:'開く瞬間は、息を弱く',kind:'b',air:'弱い息'},
    p:{title:'両くちびるを閉じる',sub:'開く瞬間に、息を強く',kind:'p',air:'強い息'},
    m:{title:'くちびるは閉じたまま',sub:'音は鼻へ響かせる',kind:'m',air:'鼻に響く'},
    f:{title:'上の歯を下くちびるへ',sub:'口角は少しだけ内側へ。細い息を流す',kind:'f',air:'細い息'}
  };
  var selected='b', ctx=null, activeNodes=[], recorder=null, stream=null, chunks=[], recordingUrl='', playback=null, modelAudio=null, articulationView='both', articulationSpeed=.78, articulationTimer=null;
  var soundFiles={
    b:'data:audio/wav;base64,',
    p:'data:audio/wav;base64,',
    m:'data:audio/wav;base64,',
    f:'data:audio/wav;base64,'
  };
  var quizOrder=['p','m','b','f'], quizIndex=0, quizAnswered=false, quizScore=0;

  function el(id){return document.getElementById(id)}
  function audioCtx(){
    if(!ctx){
      var AC=window.AudioContext||window.webkitAudioContext;
      if(AC) ctx=new AC();
    }
    if(ctx&&ctx.state==='suspended') ctx.resume().catch(function(){});
    return ctx;
  }
  function stopAudio(){
    activeNodes.forEach(function(n){try{n.stop&&n.stop()}catch(e){} try{n.disconnect&&n.disconnect()}catch(e){}});
    activeNodes=[];
  }
  function noiseBuffer(c,dur){
    var sr=c.sampleRate, len=Math.max(1,Math.floor(sr*dur)), b=c.createBuffer(1,len,sr), d=b.getChannelData(0);
    for(var i=0;i<len;i++) d[i]=Math.random()*2-1;
    return b;
  }
  function gainEnv(g,now,peak,attack,hold,release){
    g.gain.cancelScheduledValues(now);
    g.gain.setValueAtTime(0.0001,now);
    g.gain.exponentialRampToValueAtTime(Math.max(0.0002,peak),now+attack);
    g.gain.setValueAtTime(Math.max(0.0002,peak),now+attack+hold);
    g.gain.exponentialRampToValueAtTime(0.0001,now+attack+hold+release);
  }
  function burst(c, now, strong){
    var src=c.createBufferSource(), hp=c.createBiquadFilter(), g=c.createGain();
    src.buffer=noiseBuffer(c,strong?0.13:0.055);
    hp.type='highpass'; hp.frequency.value=strong?1800:1200; hp.Q.value=.45;
    gainEnv(g,now,strong?.45:.22,.003,strong?.045:.014,strong?.07:.025);
    src.connect(hp).connect(g).connect(c.destination);
    src.start(now); src.stop(now+(strong?.14:.065));
    activeNodes.push(src);
  }
  function hum(c, now){
    var master=c.createGain(), lp=c.createBiquadFilter();
    lp.type='lowpass'; lp.frequency.value=900; lp.Q.value=.7;
    gainEnv(master,now,.16,.025,.24,.09);
    [125,250,375].forEach(function(freq,i){
      var o=c.createOscillator(), g=c.createGain();
      o.type='sine'; o.frequency.value=freq; g.gain.value=[1,.42,.18][i];
      o.connect(g).connect(lp);
      o.start(now); o.stop(now+.38); activeNodes.push(o);
    });
    lp.connect(master).connect(c.destination);
  }
  function fricative(c, now){
    var src=c.createBufferSource(), bp=c.createBiquadFilter(), g=c.createGain();
    src.buffer=noiseBuffer(c,.38);
    bp.type='bandpass'; bp.frequency.value=5200; bp.Q.value=.55;
    gainEnv(g,now,.19,.02,.27,.08);
    src.connect(bp).connect(g).connect(c.destination);
    src.start(now); src.stop(now+.4); activeNodes.push(src);
  }
  function playSynthetic(letter){
    stopAudio();
    var c=audioCtx(); if(!c)return false;
    var now=c.currentTime+.025;
    if(letter==='b') burst(c,now,false);
    else if(letter==='p') burst(c,now,true);
    else if(letter==='m') hum(c,now);
    else if(letter==='f') fricative(c,now);
    return true;
  }
  function play(letter){
    stopAudio();
    try{
      if(modelAudio){modelAudio.pause();modelAudio.currentTime=0}
      modelAudio=new Audio();
      modelAudio.preload='auto';
      modelAudio.playsInline=true;
      modelAudio.volume=1;
      modelAudio.src=soundFiles[letter];
      modelAudio.load();
      var p=modelAudio.play();
      if(p&&typeof p.catch==='function'){
        p.catch(function(){playSynthetic(letter)});
      }
      return true;
    }catch(e){
      return playSynthetic(letter);
    }
  }
  function setArtPlaying(letter,duration){
    var box=el('initialsFocusVisual');
    if(!box||letter!==selected)return;
    if(articulationTimer){clearTimeout(articulationTimer);articulationTimer=null}
    box.classList.remove('is-playing'); void box.offsetWidth; box.classList.add('is-playing');
    var d=duration||Math.round((articulationSpeed<.7?4300:3200));
    articulationTimer=setTimeout(function(){if(box)box.classList.remove('is-playing')},d);
  }
  function replayArtSilent(letter){
    // Playback of the instructional motion is intentionally silent.
    // Articulation frame transition is now tied to is-playing for f and m.
    stopAudio();
    try{if('speechSynthesis' in window)window.speechSynthesis.cancel()}catch(e){}
    setArtPlaying(letter);
  }
  function playGuide(letter){
    stopAudio();
    var item=guide[letter];
    if(!item)return play(letter);
    setArtPlaying(letter);
    try{
      if(typeof window.playMachine==='function'){
        var r=window.playMachine(item.hanzi,null,false);
        if(r&&typeof r.then==='function')r.then(function(audio){try{if(audio&&articulationSpeed<.7){audio.playbackRate=.78;audio.defaultPlaybackRate=.78}}catch(e){}}).catch(function(){play(letter)});
        else if(r&&typeof r.catch==='function')r.catch(function(){play(letter)});
        return true;
      }
    }catch(e){}
    try{
      if('speechSynthesis' in window){
        window.speechSynthesis.cancel();
        var u=new SpeechSynthesisUtterance(item.hanzi); u.lang='zh-CN'; u.rate=articulationSpeed<.7?.62:.78; u.pitch=1;
        u.onerror=function(){play(letter)};
        window.speechSynthesis.speak(u); return true;
      }
    }catch(e2){}
    return play(letter);
  }
  function setStep(n){
    document.querySelectorAll('.initials-progress span').forEach(function(x){
      var k=Number(x.dataset.initialStep);
      x.classList.toggle('is-current',k===n);
      x.classList.toggle('is-done',k<n)
    })
  }
  // 10.108.54: coherent front/profile artwork with visible articulation frames.
  function artPortrait(letter,view){
    var prefix=letter==='m'?'m':'f';
    var name=prefix+'-child-'+view;
    var alt=view==='front'?'正面の口の形':'横から見た口と鼻';
    return '<span class="art-child-portrait art-child-'+view+'" role="img" aria-label="'+letter+' '+alt+'">'+
      '<img class="art-base-frame" src="./assets/articulation/'+name+'.png" alt="'+alt+'">'+
      '<img class="art-motion-frame" src="./assets/articulation/'+name+'-motion.png" alt="" aria-hidden="true">'+
      '<i class="art-dynamic-hint" aria-hidden="true"></i></span>';
  }
  function articulationSide(letter){
    if(letter==='m'||letter==='f')return artPortrait(letter,'side');
    return '';
  }
  function frontArt(letter){
    if(letter==='m'||letter==='f')return artPortrait(letter,'front');
    var extra='';
    if(letter==='b'||letter==='p'||letter==='f')extra+='<i class="af-air a1"></i><i class="af-air a2"></i><i class="af-air a3"></i>';
    return '<span class="art-front-face is-'+letter+'" aria-hidden="true"><i class="af-bridge"></i><i class="af-nose"><u class="af-ala left"></u><u class="af-ala right"></u><b class="af-nostril left"></b><b class="af-nostril right"></b></i><i class="af-upper-lip"></i><i class="af-mouth-gap"></i><i class="af-lower-lip"></i><i class="af-teeth"></i><i class="af-corner left"></i><i class="af-corner right"></i>'+extra+'</span>';
  }
  function applyArtView(box){
    if(!box)return;
    box.classList.remove('view-front','view-side','view-both');
    box.classList.add('view-'+articulationView);
    box.querySelectorAll('[data-art-view]').forEach(function(b){b.classList.toggle('is-active',b.dataset.artView===articulationView)});
  }
  function wireArtControls(letter,needSide){
    var box=el('initialsFocusVisual');if(!box)return;
    var playBtn=box.querySelector('[data-art-play]');
    if(playBtn)playBtn.onclick=function(){replayArtSilent(letter)};
    box.querySelectorAll('.art-view-front,.art-view-side').forEach(function(card){
      card.setAttribute('role','button');card.setAttribute('tabindex','0');
      card.setAttribute('aria-label','口の動きをもう一度見る（音声なし）');
      card.onclick=function(){replayArtSilent(letter)};
      card.onkeydown=function(e){if(e.key==='Enter'||e.key===' '){e.preventDefault();replayArtSilent(letter)}};
    });
    box.querySelectorAll('[data-art-speed]').forEach(function(b){b.onclick=function(){articulationSpeed=b.dataset.artSpeed==='slow'?.62:.78;box.style.setProperty('--art-cycle',articulationSpeed<.7?'4.3s':'3.2s');box.querySelectorAll('[data-art-speed]').forEach(function(x){x.classList.toggle('is-active',x===b)})}});
    box.querySelectorAll('[data-art-view]').forEach(function(b){b.onclick=function(){if(b.disabled)return;articulationView=b.dataset.artView;applyArtView(box)}});
    if(!needSide){articulationView='front';box.querySelectorAll('[data-art-view="side"],[data-art-view="both"]').forEach(function(b){b.disabled=true})}
    else if(articulationView==='front')articulationView='both';
    applyArtView(box);
  }
  function renderFocusVisual(letter){
    var box=el('initialsFocusVisual'),v=focusVisuals[letter]; if(!box||!v)return;
    if(articulationTimer){clearTimeout(articulationTimer);articulationTimer=null;}
    var needSide=(letter==='m'||letter==='f');
    box.className='initials-focus-visual articulation-stage art-player is-'+letter+(needSide?' has-side':'');
    var side=needSide?('<div class="art-view art-view-side"><span class="art-view-label">横から</span>'+articulationSide(letter)+'<small class="art-side-note">'+(letter==='m'?'鼻腔へひびく':'歯とくちびるのすき間')+'</small></div>'):'';
    box.innerHTML='<div class="art-stage-head"><span>口の動きアニメーション</span><small>'+(needSide?'正面で口の形、横から音の通り道':'口の形と息の動きを見てまねよう')+'</small></div>'+
      '<div class="art-player-controls"><button type="button" class="art-play-main" data-art-play><span>▶</span> 動きを見る</button><div class="art-speed" aria-label="再生スピード"><button type="button" data-art-speed="slow" class="is-active">ゆっくり</button><button type="button" data-art-speed="normal">ふつう</button></div></div>'+
      '<div class="art-view-tabs" aria-label="見方"><button type="button" data-art-view="front">正面</button><button type="button" data-art-view="side">横から</button><button type="button" data-art-view="both">いっしょに見る</button></div>'+
      '<div class="art-player-stage"><div class="art-view art-view-front"><span class="art-view-label">正面</span><span class="art-playing-badge">▶ 再生中</span>'+frontArt(letter)+'</div>'+side+'</div>'+
      '<div class="art-stage-copy"><b>'+v.title+'</b><small>'+v.sub+'</small><em>'+v.air+'</em></div>';
    box.style.setProperty('--art-cycle',articulationSpeed<.7?'4.3s':'3.2s');
    wireArtControls(letter,needSide);
  }
  function select(letter){
    selected=letter;
    document.querySelectorAll('.initials-letter-card,.initials-free-choice button').forEach(function(b){
      b.classList.toggle('is-active',b.dataset.letter===letter)
    });
    var f=el('initialsFocusLetter'),s=el('initialsFocusSyllable'),t=el('initialsFocusTip');
    if(f)f.textContent=letter;
    if(s)s.textContent=guide[letter].hanzi+' '+guide[letter].pinyin+' · '+sounds[letter].mark;
    if(t)t.textContent=tips[letter];
    renderFocusVisual(letter);
    renderToneButtons()
  }
  function renderToneButtons(){
    var box=el('initialsToneButtons'); if(!box)return;
    box.replaceChildren();
    var b=document.createElement('button');
    b.type='button'; b.className='initial-guide-button'; b.textContent='▶ '+selected+' のお手本を聞く（'+guide[selected].hanzi+'）';
    b.addEventListener('click',function(){playGuide(selected)});
    box.appendChild(b);
    var raw=document.createElement('button'); raw.type='button'; raw.className='initial-raw-button';
    raw.textContent='息・口の動きだけを聞く'; raw.addEventListener('click',function(){setArtPlaying(selected);play(selected)}); box.appendChild(raw)
  }
  function renderLetters(){
    var g=el('initialsLetterGrid'),free=el('initialsFreeChoice'); if(!g||!free)return;
    g.replaceChildren(); free.replaceChildren();
    letters.forEach(function(letter,i){
      var b=document.createElement('button'); b.type='button'; b.className='initials-letter-card'; b.dataset.letter=letter;
      var cue={
        b:{ipa:'[p]',kind:'air air-soft',label:'息は弱く'},
        p:{ipa:'[pʰ]',kind:'air air-strong',label:'息を強く'},
        m:{ipa:'[m]',kind:'nose',label:'鼻に響く'},
        f:{ipa:'[f]',kind:'air air-thin',label:'細い息'}
      }[letter];
      var icon=letter==='m'
        ? '<span class="initial-cue-icon '+cue.kind+'" aria-hidden="true"><i></i><i></i><i></i></span>'
        : '<span class="initial-cue-icon '+cue.kind+'" aria-hidden="true"><i></i><i></i><i></i></span>';
      b.innerHTML='<span class="big">'+letter+'</span><span class="initial-ipa">'+cue.ipa+'</span><span class="initial-articulation">'+icon+'<em>'+cue.label+'</em></span>';
      b.addEventListener('click',function(){select(letter);playGuide(letter)}); g.appendChild(b);
      var c=document.createElement('button'); c.type='button'; c.dataset.letter=letter;
      c.innerHTML='<span class="free-letter">'+letter+'</span><span class="free-ipa">'+sounds[letter].mark+'</span>';
      c.addEventListener('click',function(){setStep(3);select(letter);playGuide(letter)}); free.appendChild(c)
    });
    select('b')
  }
  function renderQuiz(){
    var box=el('initialsQuizChoices'); if(!box)return; box.replaceChildren();
    letters.forEach(function(letter){
      var b=document.createElement('button'); b.type='button'; b.textContent=letter;
      b.addEventListener('click',function(){answerQuiz(letter,b)}); box.appendChild(b)
    });
    var count=el('initialsQuizCount'); if(count)count.textContent=(quizIndex+1)+' / '+quizOrder.length;
    var fb=el('initialsQuizFeedback'); if(fb){fb.textContent='';fb.className='initials-feedback'}
    var next=el('initialsQuizNext'); if(next)next.hidden=true; quizAnswered=false
  }
  function playQuiz(){playGuide(quizOrder[quizIndex])}
  function answerQuiz(letter,button){
    if(quizAnswered)return; quizAnswered=true;
    var right=quizOrder[quizIndex],fb=el('initialsQuizFeedback');
    if(letter===right){
      quizScore++; button.classList.add('is-correct');
      if(fb){fb.textContent='いい耳！ '+right+' のお手本だよ ✓';fb.className='initials-feedback is-good'}
    }else{
      button.classList.add('is-wrong');
      var rb=Array.prototype.find.call(el('initialsQuizChoices').children,function(x){return x.textContent===right});
      if(rb)rb.classList.add('is-correct');
      if(fb){fb.textContent='今回は '+right+'。呼読音の最初の音と、息の出方をもう一度比べよう';fb.className='initials-feedback is-bad'}
    }
    var next=el('initialsQuizNext');
    if(quizIndex===quizOrder.length-1){
      if(next)next.hidden=true;
      window.setTimeout(function(){if(quizAnswered)finishQuiz()},650)
    }else if(next){next.hidden=false;next.textContent='次の問題へ →'}
  }
  function nextQuiz(){
    if(!quizAnswered)return;
    if(quizIndex<quizOrder.length-1){quizIndex++;renderQuiz();playQuiz();return}
    finishQuiz()
  }
  function goBackToInitialRoad(){
    var back=document.getElementById('pinyinLessonBack');
    if(back)back.click();
    window.setTimeout(function(){
      var world=document.querySelector('.pinyin-world[data-stage-id="P3-P8"]');
      var open=world&&world.querySelector('.pinyin-world-open');
      if(open)open.click();
      window.setTimeout(function(){
        var p4=document.querySelector('.pinyin-node[data-unit-id="P4"]');
        if(p4){p4.classList.add('is-next-focus');p4.scrollIntoView({block:'center',behavior:'smooth'})}
      },90);
    },90);
  }
  function retryQuiz(){
    var panel=el('initialsQuizPanel'),result=el('initialsResult'),reward=el('initialsReward');
    if(result)result.hidden=true;if(reward)reward.hidden=true;if(panel)panel.hidden=false;
    quizIndex=0;quizScore=0;renderQuiz();setStep(4);
    requestAnimationFrame(function(){if(panel)panel.scrollIntoView({block:'start',behavior:'smooth'})});
  }
  function finishQuiz(){
    var panel=el('initialsQuizPanel'),result=el('initialsResult'),reward=el('initialsReward');
    var passed=quizScore>=3,total=quizOrder.length;
    if(panel)panel.hidden=true;
    if(result)result.hidden=false;
    if(reward)reward.hidden=!passed;
    setStep(4);

    var badge=el('initialsResultBadge'),title=el('initialsResultTitle'),score=el('initialsResultScore'),msg=el('initialsResultMessage'),action=el('initialsResultAction');
    if(badge){badge.textContent=passed?'✓':'↻';badge.className='initials-result-badge '+(passed?'is-pass':'is-retry')}
    if(title)title.textContent=passed?'ミニチェック合格！':'あと一歩！';
    if(score)score.textContent=total+'問中 '+quizScore+'問正解';
    if(msg)msg.textContent=passed?'b・p・m・f の違いを聞き分けられたよ。':'3問以上でクリア。苦手な音をもう一度聞いて挑戦しよう。';
    if(action){
      action.textContent=passed?'声母の森へ戻る →':'もう一度やってみる';
      action.onclick=passed?goBackToInitialRoad:retryQuiz;
    }

    if(passed){
      try{localStorage.setItem('koepandaInitialP3Complete','1');window.dispatchEvent(new CustomEvent('koepandaInitialProgressChanged',{detail:{P3:true}}))}catch(e){}
    }else{
      try{localStorage.removeItem('koepandaInitialP3Complete');window.dispatchEvent(new CustomEvent('koepandaInitialProgressChanged',{detail:{P3:false}}))}catch(e){}
    }
    var celebration={score:quizScore,total:total,passed:passed,title:passed?'ミニチェック合格！':'あと一歩！',message:passed?(quizScore===total?'b・p・m・f、4問ぜんぶ正解！ 音の違いをばっちり聞き分けられたよ。':'b・p・m・f の違いを聞き分けられたよ。あと1問で満点！'):'苦手な音をもう一度確認して、再チャレンジしよう。'};
    if(window.koepandaAttachResultReplay)window.koepandaAttachResultReplay(result,celebration);
    if(window.koepandaQueueResultCelebration)window.koepandaQueueResultCelebration(celebration,90);
    else if(window.koepandaShowResultCelebration)window.setTimeout(function(){window.koepandaShowResultCelebration(celebration)},90);
  }
  function mimeType(){
    if(typeof MediaRecorder==='undefined')return '';
    var arr=['audio/mp4','audio/webm;codecs=opus','audio/webm'];
    for(var i=0;i<arr.length;i++){try{if(MediaRecorder.isTypeSupported(arr[i]))return arr[i]}catch(e){}}
    return ''
  }
  async function toggleRecord(){
    var btn=el('initialsRecord'),fb=el('initialsImitateFeedback');
    if(recorder&&recorder.state==='recording'){try{recorder.stop()}catch(e){}return}
    if(!navigator.mediaDevices||!navigator.mediaDevices.getUserMedia||typeof MediaRecorder==='undefined'){
      if(fb)fb.textContent='このブラウザでは録音が使えません。';return
    }
    try{
      stopAudio(); chunks=[]; stream=await navigator.mediaDevices.getUserMedia({audio:true});
      var mt=mimeType(); recorder=new MediaRecorder(stream,mt?{mimeType:mt}:undefined);
      recorder.ondataavailable=function(e){if(e.data&&e.data.size)chunks.push(e.data)};
      recorder.onstop=function(){
        var blob=new Blob(chunks,{type:recorder.mimeType||mt||'audio/mp4'});
        if(recordingUrl)URL.revokeObjectURL(recordingUrl); recordingUrl=URL.createObjectURL(blob);
        if(stream){stream.getTracks().forEach(function(t){t.stop()});stream=null}
        btn.textContent='↻ もう一度録音'; btn.classList.remove('is-recording');
        el('initialsPlayback').disabled=false;
        if(fb){fb.textContent='録音できたよ。お手本と聞きくらべてみよう 👂';fb.className='initials-feedback is-good'}
        setStep(3)
      };
      recorder.start(); btn.textContent='■ 録音を止める'; btn.classList.add('is-recording');
      if(fb){fb.textContent='録音中… '+selected+' のお手本の最初の音を意識してまねしよう';fb.className='initials-feedback'}
    }catch(e){if(fb)fb.textContent='マイクの許可を確認してね。'}
  }
  function playRecording(){
    if(!recordingUrl)return;
    var btn=el('initialsPlayback');if(btn){btn.classList.remove('is-pressed');void btn.offsetWidth;btn.classList.add('is-pressed');setTimeout(function(){btn.classList.remove('is-pressed')},180)}
    try{if(playback)playback.pause();playback=new Audio(recordingUrl);if(btn)btn.classList.add('is-playing');playback.addEventListener('ended',function(){if(btn)btn.classList.remove('is-playing')},{once:true});var pr=playback.play();if(pr&&pr.catch)pr.catch(function(){if(btn)btn.classList.remove('is-playing')})}catch(e){if(btn)btn.classList.remove('is-playing')}
  }
  function init(){
    if(!el('kidsInitialsLesson'))return;
    var initialReward=el('initialsReward'),initialResult=el('initialsResult');
    if(initialReward)initialReward.hidden=true;
    if(initialResult)initialResult.hidden=true;
    renderLetters();
    document.querySelectorAll('.air-card').forEach(function(b){b.addEventListener('click',function(){setStep(2);play(b.dataset.air)})});
    document.querySelectorAll('.mouth-sound-card').forEach(function(b){b.addEventListener('click',function(){setStep(2);play(b.dataset.mouth)})});
    el('initialsToQuiz').disabled=false;
    el('initialsRecord').addEventListener('click',toggleRecord);
    el('initialsPlayback').addEventListener('click',playRecording);
    el('initialsToQuiz').addEventListener('click',function(){
      el('initialsQuizPanel').hidden=false; this.closest('.initials-imitate-panel').hidden=true;
      quizIndex=0; quizScore=0; renderQuiz(); setStep(4);
      requestAnimationFrame(function(){el('initialsQuizPanel').scrollIntoView({block:'start',behavior:'smooth'})})
    });
    el('initialsQuizListen').addEventListener('click',playQuiz);
    el('initialsQuizNext').addEventListener('click',nextQuiz)
  }
  window.koepandaIsInitialUnitComplete=function(id){
    if(id==='P3'){try{return localStorage.getItem('koepandaInitialP3Complete')==='1'}catch(e){return false}}
    return false
  };
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init()
})();